const accountsKey='mnu-community-demo-accounts',sessionKey='mnu-community-demo-session';let authUser=null;try{authUser=JSON.parse(localStorage.getItem(sessionKey)||'null')}catch{}const userStateKey=email=>email?`mnu-community-data:${String(email).toLowerCase()}`:'mnu-community-demo-guest';function emptyState(){return{applications:[],orientation:null,joined:[],orgSubmission:null,registered:[]}}function loadUserState(email=authUser?.email){try{return{...emptyState(),...(JSON.parse(localStorage.getItem(userStateKey(email))||'null')||{})}}catch{return emptyState()}}let state=loadUserState();state.applications||=[];state.joined||=[];state.registered||=[];if(authUser&&!state.joined.includes('ai-club')){state.joined.unshift('ai-club');try{localStorage.setItem(userStateKey(authUser.email),JSON.stringify(state))}catch{}}
