const toastEl=$('#toast');let toastTimer;function toast(m){toastEl.textContent=m;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2500)}function save(){try{localStorage.setItem(userStateKey(),JSON.stringify(state))}catch{toast('Не удалось сохранить данные в этом браузере')}}
