function setView(name){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#crumbTitle').textContent=viewNames[name]||'Главная';window.scrollTo({top:0,behavior:'smooth'});if(name==='applications')renderApplications();if(name==='catalog')renderCatalog($('#catalogSearch').value);if(name==='myclub')renderMyOrganizations();if(name==='create')restoreSavedOrgSubmission();if(name==='orientation')restoreOrientationQuestions()}
