function orgCard(c,featured=false){return `<article class="org-card ${featured?'featured-org-card':''}"><div class="org-card-top"><span class="club-symbol symbol-${c.color}">${esc(c.short)}</span><span class="org-category">${esc(c.category)}</span></div><h3>${esc(c.name)}</h3><p>${esc(c.about)}</p><div class="org-tags">${c.tags.slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="org-card-bottom"><span>Демо-профиль · MNU</span><button class="card-arrow" data-open-org="${c.id}" aria-label="Открыть ${esc(c.name)}">↗</button></div></article>`}
$('#featuredOrgs').innerHTML=clubs.slice(0,3).map(c=>orgCard(c,true)).join('');
let selectedCategory='Все направления';const categories=['Все направления','Технологии','Карьера','Медиа','Общество','Спорт','Культура','Образование','Лидерство','Наука'];$('#categoryChips').innerHTML=categories.map((c,i)=>`<button class="category-chip ${i===0?'active':''}" data-category="${c}">${c}</button>`).join('');
function renderCatalog(query=''){const filtered=clubs.filter(c=>(selectedCategory==='Все направления'||c.category.toLowerCase().includes(selectedCategory.toLowerCase()))&&`${c.name} ${c.about} ${c.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));$('#catalogGrid').innerHTML=filtered.map(c=>orgCard(c)).join('')||'<div class="empty-state">Не нашлось организаций по такому запросу. Попробуй другое направление.</div>';$$('[data-open-org]').forEach(b=>b.onclick=()=>openOrg(b.dataset.openOrg));if(state.orientation?.recommendations?.length){const best=state.orientation.recommendations[0];const c=clubs.find(x=>x.id===best);$('#catalogMatch').hidden=false;$('#catalogMatch').innerHTML=`<span class="match-spark" aria-hidden="true"></span><div><small>ПО РЕЗУЛЬТАТАМ ТВОЕГО ПОДБОРА</small><b>Начни с ${esc(c?.name||'подходящих организаций')}</b><p>Мы учли твои ответы о том, что тебе интересно.</p></div><button class="quiet-link" data-open-org="${esc(best)}">Посмотреть <span>→</span></button>`;$$('[data-open-org]').forEach(b=>b.onclick=()=>openOrg(b.dataset.openOrg))}}
renderCatalog();$('#catalogSearch').addEventListener('input',e=>renderCatalog(e.target.value));$$('[data-category]').forEach(b=>b.onclick=()=>{selectedCategory=b.dataset.category;$$('[data-category]').forEach(x=>x.classList.toggle('active',x===b));renderCatalog($('#catalogSearch').value)});
function openOrg(id){const c=clubs.find(x=>x.id===id);if(!c)return;const member=state.joined.includes(id);$('#orgDetailContent').innerHTML=`<div class="detail-hero detail-${c.color}"><div class="detail-orb">${esc(c.short)}</div><div><span class="detail-category">${esc(c.category.toUpperCase())}</span><h1>${esc(c.name)}</h1><p>${esc(c.about)}</p><div class="detail-tags">${c.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div>${member?`<span class="member-tag">Ты участник</span>`:`<button class="primary-button" data-apply="${c.id}">Хочу вступить ↗</button>`}</div><div class="detail-columns"><section class="detail-section"><div class="section-eyebrow">ОБ ОРГАНИЗАЦИИ</div><h2>Что вы будете делать</h2><p>${esc(c.about)} Организация собирает участников с разным опытом: можно прийти с идеей, вопросом или желанием попробовать новое.</p><div class="detail-facts"><div><b>Демо-профиль</b><small>сведения примерные</small></div><div><b>Открытый</b><small>набор в течение семестра</small></div><div><b>3 этапа</b><small>до подтверждения участия</small></div></div><h3>Как проходит вступление</h3><div class="detail-steps"><span><i>1</i><b>Контакты</b><small>Оставь данные</small></span><span><i>2</i><b>Отбор</b><small>Познакомься с командой</small></span><span><i>3</i><b>Участник</b><small>После решения клуба</small></span></div></section><aside class="detail-aside"><div class="aside-card"><span class="aside-icon" aria-hidden="true"></span><h3>${member?'Ты уже в команде':`Хочешь в ${esc(c.name)}?`}</h3><p>${member?'Открой страницу своей организации и смотри, что впереди.':'Сначала расскажи организаторам, как с тобой связаться. Они пригласят на следующий этап отбора.'}</p><button class="primary-button full-button" data-apply="${c.id}">${member?`Открыть страницу ${esc(c.name)}`:'Оставить контактные данные →'}</button><small>${member?'События, фото и контакты собраны на странице организации.':'Твои контакты увидят только организаторы этой организации.'}</small></div></aside></div>`;$$('[data-apply]').forEach(apply=>apply.onclick=()=>{if(member){setView('myclub');return}ensureSignedIn(()=>openApplication(c))});setView('org-detail')}
