const appDialog=$('#applicationDialog');function openApplication(c){$('#applyOrgName').textContent=c.name;const form=$('#applicationForm');form.dataset.orgId=c.id;form.reset();const user=authUser||{};form.querySelector('[name="name"]').value=user.name||'';form.querySelector('[name="course"]').value=user.course||'';const contactEmail=authUser?.email||'',emailField=form.querySelector('input[type="email"]');appDialog.showModal();emailField.value=contactEmail;requestAnimationFrame(()=>{emailField.value=contactEmail})}$('.dialog-close').onclick=()=>appDialog.close();appDialog.addEventListener('click',e=>{if(e.target===appDialog)appDialog.close()});
$('#applicationForm').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),orgId=f.dataset.orgId,c=clubs.find(x=>x.id===orgId);state.applications.unshift({id:`app-${Date.now()}`,orgId,orgName:c.name,status:'contacts',name:fd.get('name'),email:fd.get('email'),contact:fd.get('contact'),course:fd.get('course'),motivation:fd.get('motivation'),created:new Date().toLocaleDateString('ru-RU')});save();f.reset();appDialog.close();renderApplications();toast('Контактные данные отправлены. Заявка на этапе 1 из 3.');setView('applications')});
function renderApplications(){const list=$('#applicationsList');$('#applicationCount').textContent=state.applications.filter(a=>a.status!=='member').length;$('#emptyApplications').hidden=state.applications.length>0;list.innerHTML=state.applications.map(a=>{const step=a.status==='contacts'?1:a.status==='selection'?2:3;const label=a.status==='contacts'?'Контактные данные получены':a.status==='selection'?'Организация рассматривает заявку':'Одобрено · ты участник';return `<article class="application-card"><div class="application-head"><span class="club-symbol symbol-${clubs.find(c=>c.id===a.orgId)?.color||'violet'}">${esc(clubs.find(c=>c.id===a.orgId)?.short||'M')}</span><div><small>ЗАЯВКА В ОРГАНИЗАЦИЮ</small><h3>${esc(a.orgName)}</h3></div><span class="application-state state-${a.status}">${label}</span></div><div class="application-steps"><div class="app-step done"><i>✓</i><span><b>Контакты</b><small>${esc(a.name)} · ${esc(a.contact)}</small></span></div><div class="step-line ${step>1?'passed':''}"></div><div class="app-step ${step>=2?'done':''} ${step===2?'current':''}"><i>${step>=2?'✓':'2'}</i><span><b>Отбор</b><small>${step===1?'Следующий шаг — знакомство с командой':step===2?'Ожидай решения организации':'Отбор пройден'}</small></span></div><div class="step-line ${step>=3?'passed':''}"></div><div class="app-step ${step>=3?'done':''}"><i>${step>=3?'✓':'3'}</i><span><b>Участник</b><small>${step>=3?'Добро пожаловать в команду':'После одобрения заявки'}</small></span></div></div>${a.status==='contacts'?`<div class="application-next"><p><b>Контакты отправлены.</b> Организация свяжется с тобой. Когда начнётся знакомство и отбор, отметь это здесь.</p><button class="outline-button" data-selection="${a.id}">Перейти к отбору →</button><button class="text-link" data-withdraw="${a.id}">Отозвать заявку</button></div>`:a.status==='selection'?`<div class="application-next"><p><b>Ты на этапе отбора.</b> Статус участника появится только после решения организаторов.</p><button class="demo-approve" data-approve="${a.id}">Демо: отметить успешный отбор</button><button class="text-link" data-withdraw="${a.id}">Отозвать заявку</button></div>`:`<div class="approved-banner">Заявка одобрена организацией — теперь ты участник. <button data-open-club="${a.orgId}">Открыть страницу →</button></div>`}</article>`}).join('');$$('[data-selection]').forEach(b=>b.onclick=()=>{const a=state.applications.find(x=>x.id===b.dataset.selection);a.status='selection';save();renderApplications();toast('Этап отбора начат. Решение принимает организация.')});$$('[data-withdraw]').forEach(b=>b.onclick=()=>{state.applications=state.applications.filter(a=>a.id!==b.dataset.withdraw);save();renderApplications();toast('Заявка отозвана')});$$('[data-approve]').forEach(b=>b.onclick=()=>{const a=state.applications.find(x=>x.id===b.dataset.approve);a.status='member';if(!state.joined.includes(a.orgId))state.joined.push(a.orgId);save();renderApplications();toast('Статус участника сохранён в демо-заявке')});$$('[data-open-club]').forEach(b=>b.onclick=()=>{const id=b.dataset.openClub;if(id==='ai-club')setView('myclub');else openOrg(id)});updateAccountChrome()}
