function writeAccounts(accounts){try{localStorage.setItem(accountsKey,JSON.stringify(accounts));return true}catch{return false}}
function randomSalt(){const b=crypto.getRandomValues(new Uint8Array(16));return [...b].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function passwordDigest(password,saltHex){const salt=Uint8Array.from(saltHex.match(/.{2}/g)||[],x=>parseInt(x,16));const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:120000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function setAuthMode(mode){authMode=mode;const registration=mode==='register',passwordField=$('#authForm').querySelector('[name="password"]');$('#authError').hidden=true;if(registration)passwordField.minLength=8;else passwordField.removeAttribute('minlength');$('#authNameField').hidden=!registration;$('#authNameField input').required=registration;$('#authCourseField').hidden=!registration;$('#authConsent').hidden=!registration;$('#authConsent input').required=registration;passwordField.autocomplete=registration?'new-password':'current-password';$('#authEyebrow').textContent=registration?'ТВОЙ ПРОФИЛЬ':'АККАУНТ СТУДЕНТА';$('#authTitle').textContent=registration?'Регистрация в MNU Clubs':'Войти в MNU Clubs';$('#authDescription').textContent=registration?'Создай профиль, чтобы сохранять заявки и события.':'Войди, чтобы отправлять заявки и следить за событиями.';$('#authSubmit').innerHTML=registration?'Создать аккаунт <span>→</span>':'Войти <span>→</span>';$('#authSwitchLabel').textContent=registration?'Уже есть аккаунт?':'Нет аккаунта?';$('#authSwitch').textContent=registration?'Войти':'Создать аккаунт'}
function openAuth(mode='login',after=null){pendingAfterAuth=after;setAuthMode(mode);$('#authForm').reset();$('#authDialog').showModal()}
function ensureSignedIn(action){if(authUser){action?.();return true}openAuth('login',action);return false}
function restoreSignedInUser(user,{registered=false}={}){authUser={name:user.name,email:user.email,course:user.course||'1 курс',interests:user.interests||'',notifications:user.notifications!==false};try{localStorage.setItem(sessionKey,JSON.stringify(authUser))}catch{}state=loadUserState(authUser.email);state.joined||=[];if(!state.joined.includes('ai-club'))state.joined.unshift('ai-club');save();renderApplications();updateAccountChrome();if($('#view-myclub').classList.contains('active'))renderMyOrganizations();const next=pendingAfterAuth;pendingAfterAuth=null;authDialog.close();toast(registered?'Регистрация завершена — ты вошёл(ла) в профиль.':'Вы успешно вошли в аккаунт.');if(typeof next==='function')next()}

function restoreSavedOrgSubmission(){const box=$('#orgSubmitted'),form=$('#orgForm'),saved=state.orgSubmission;if(!box||!form||!saved?.data)return;form.hidden=true;box.hidden=false;box.innerHTML=`<div class="submitted-mark">✓</div><div class="section-eyebrow">ЗАЯВКА ОТПРАВЛЕНА</div><h2>${esc(saved.data.orgName)} — на рассмотрении университета</h2><p>Заявка сохранена в демо-профиле этого браузера.</p><div class="submitted-status"><span>01</span><b>На рассмотрении</b><small>Отправлено ${esc(saved.date||'')}</small></div><button class="outline-button" id="newOrgRequest">Редактировать заявку</button>`;$('#newOrgRequest').onclick=()=>{for(const [key,value] of Object.entries(saved.data)){if(form.elements[key]&&form.elements[key].type!=='checkbox')form.elements[key].value=value}form.hidden=false;box.hidden=true;setWizardStep(1)}}
function renderMyOrganizations(){const hasAI=state.joined.includes('ai-club'),others=state.joined.filter(id=>id!=='ai-club').map(id=>clubs.find(c=>c.id===id)).filter(Boolean),otherBox=$('#otherOrganizations');if(otherBox){otherBox.hidden=!others.length;otherBox.innerHTML=others.length?`<div class="other-organizations-head"><div><div class="section-eyebrow">ЕЩЁ В ТВОЁМ СПИСКЕ</div><h2>Другие организации</h2></div><span>${others.length}</span></div><div class="other-organizations-grid">${others.map(c=>`<article class="other-org-card"><span class="club-symbol symbol-${c.color}">${esc(c.short)}</span><div><b>${esc(c.name)}</b><small>${esc(c.category)}</small></div><button type="button" data-other-org="${c.id}" aria-label="Открыть ${esc(c.name)}">↗</button></article>`).join('')}</div>`:'';$$('[data-other-org]').forEach(b=>b.onclick=()=>openOrg(b.dataset.otherOrg))}if(hasAI){$('.club-cover').hidden=false;$('.club-tabs').hidden=false;$('.club-aside').hidden=false;renderClub('overview');return}$('.club-cover').hidden=true;$('.club-tabs').hidden=true;$('.club-aside').hidden=true;const names=state.joined.map(id=>clubs.find(c=>c.id===id)?.name).filter(Boolean);$('#clubContent').innerHTML=`<div class="membership-empty"><div class="section-eyebrow">МОИ ОРГАНИЗАЦИИ</div><h2>${names.length?'Твои организации':'Ты ещё не вступил(а) в организацию'}</h2><p>${names.length?`Сейчас в твоём профиле: ${names.map(esc).join(', ')}. Страницы других команд появятся после подключения их кабинетов.`:'Найди сообщество в каталоге, оставь контакты и дождись решения организаторов. Здесь появятся мероприятия, объявления и контакты команды.'}</p><button class="primary-button" id="membershipCatalogButton">Открыть каталог <span>→</span></button></div>`;$('#membershipCatalogButton').onclick=()=>setView('catalog')}
const setViewWithoutAuth=setView;setView=function(name){if(['applications','myclub','create'].includes(name)&&!authUser){ensureSignedIn(()=>setView(name));return}setViewWithoutAuth(name);[notificationDialog,helpDialog].forEach(d=>{if(d.open)d.close()})};
function openProfile(){if(!authUser){openAuth('login');return}const form=$('#profileForm');form.elements.name.value=authUser.name||'';form.elements.email.value=authUser.email||'';form.elements.course.value=authUser.course||'1 курс';form.elements.interests.value=authUser.interests||'';form.elements.notifications.checked=authUser.notifications!==false;$('#profileDialogAvatar').textContent=initials(authUser.name);profileDialog.showModal()}
const accountMenu=$('#accountMenu');function toggleAccountMenu(){if(!authUser){openAuth('login');return}const opening=accountMenu.hidden;accountMenu.hidden=!opening;$('#accountButton').setAttribute('aria-expanded',String(opening));$('#accountMenuName').textContent=authUser.name||'Профиль';$('#accountMenuEmail').textContent=authUser.email||''}$('#profileMini').onclick=toggleAccountMenu;$('#accountButton').onclick=toggleAccountMenu;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!accountMenu.hidden){accountMenu.hidden=true;$('#accountButton').setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(!accountMenu.hidden&&!e.target.closest('#accountMenu')&&!e.target.closest('#accountButton')&&!e.target.closest('#profileMini')){accountMenu.hidden=true;$('#accountButton').setAttribute('aria-expanded','false')}});$('#accountMenu').addEventListener('click',e=>{const action=e.target.closest('[data-account-action]')?.dataset.accountAction;if(!action)return;accountMenu.hidden=true;$('#accountButton').setAttribute('aria-expanded','false');if(action==='settings')openProfile();if(action==='applications')setView('applications');if(action==='organization')setView('myclub');if(action==='orientation')setView('orientation');if(action==='notifications')openNotifications();if(action==='logout')$('#logoutButton').click()});$('#authSwitch').onclick=()=>setAuthMode(authMode==='login'?'register':'login');
$('#authForm').addEventListener('input',e=>{if(e.target.matches('input')){const error=$('#authError');error.hidden=true;$('#authForm').querySelector('[name="password"]').removeAttribute('aria-invalid')}});
$('#authForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,email=form.querySelector('[name="email"]').value.trim().toLowerCase(),passwordField=form.querySelector('[name="password"]'),password=passwordField.value;try{if(!crypto?.subtle)throw new Error('Для демо-входа открой сайт по защищённому HTTPS-соединению.');const accounts=readAccounts();if(authMode==='register'){if(!form.querySelector('[name="consent"]').checked){toast('Отметь согласие на обработку данных');return}const existing=accounts.find(x=>x.email===email);if(existing){if(existing.salt&&existing.passwordHash&&await passwordDigest(password,existing.salt)===existing.passwordHash){restoreSignedInUser(existing);return}const error=$('#authError');error.textContent='Эта почта уже зарегистрирована. Введи пароль от аккаунта или укажи другую почту.';error.hidden=false;return}const salt=randomSalt(),user={name:form.querySelector('[name="name"]').value.trim(),email,course:form.querySelector('[name="course"]').value,interests:'',notifications:true,salt,passwordHash:await passwordDigest(password,salt)};if(!writeAccounts([...accounts,user]))throw new Error('Не удалось сохранить аккаунт в этом браузере.');restoreSignedInUser(user,{registered:true})}else{const user=accounts.find(x=>x.email===email);if(!user||await passwordDigest(password,user.salt)!==user.passwordHash){const error=$('#authError');error.textContent='Неверная почта или пароль. Проверь данные и попробуй снова.';error.hidden=false;passwordField.setAttribute('aria-invalid','true');return}restoreSignedInUser(user)}}catch(err){toast(err.message||'Не удалось выполнить вход')}});
$('#profileForm').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;authUser={...authUser,name:f.elements.name.value.trim(),course:f.elements.course.value,interests:f.elements.interests.value.trim(),notifications:f.elements.notifications.checked};const accounts=readAccounts().map(u=>u.email===authUser.email?{...u,...authUser}:u);if(!writeAccounts(accounts)){toast('Не удалось сохранить изменения в этом браузере');return}try{localStorage.setItem(sessionKey,JSON.stringify(authUser))}catch{}profileDialog.close();updateAccountChrome();toast('Настройки профиля сохранены')});
$('#logoutButton').onclick=()=>{try{localStorage.removeItem(sessionKey)}catch{}profileDialog.close();accountMenu.hidden=true;authUser=null;state=loadUserState();updateAccountChrome();setViewWithoutAuth('home');toast('Ты вышел(ла) из аккаунта')};
function notificationCard(kind,title,description,stateLabel,index){return `<article class="notification-item"><span class="notification-index">${String(index).padStart(2,'0')}</span><div class="notification-copy"><div class="notification-meta"><small>${kind}</small><span class="notification-status">${stateLabel}</span></div><b>${esc(title)}</b><p>${esc(description)}</p></div></article>`}function openNotifications(){const dot=$('#notificationButton i');dot.hidden=true;if(authUser?.notifications===false){$('#notificationList').innerHTML='<div class="utility-empty notification-empty"><b>Уведомления выключены</b><span>Включи их в настройках профиля, чтобы получать обновления о заявках и событиях.</span></div>';notificationDialog.showModal();return}const items=[];for(const a of state.applications){const title=a.status==='contacts'?'Контактные данные получены':a.status==='selection'?'Организация рассматривает заявку':'Участие подтверждено';const detail=a.status==='contacts'?'Организаторы свяжутся с тобой и расскажут о следующем шаге.':a.status==='selection'?'Твоя заявка сейчас на этапе отбора.':'Тебя добавили в список участников.';items.push(notificationCard('ЗАЯВКА',a.orgName,detail,title,items.length+1))}for(const idx of state.registered){const n=Number(String(idx).replace('ai-',''));const ev=initialEvents[n];if(ev)items.push(notificationCard('МЕРОПРИЯТИЕ',ev.title,`${ev.date} · ${ev.place}`,'Ты записан(а)',items.length+1))}$('#notificationList').innerHTML=items.length?items.join(''):'<div class="utility-empty notification-empty"><b>Пока нет обновлений</b><span>Здесь появятся статусы заявок и напоминания о мероприятиях.</span></div>';notificationDialog.showModal()}
$('#helpButton').onclick=()=>helpDialog.showModal();$('#notificationButton').onclick=openNotifications;$('#feedbackButton').onclick=()=>feedbackDialog.showModal();
$('#feedbackForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{const items=JSON.parse(localStorage.getItem('mnu-community-feedback')||'[]');items.push({...data,email:authUser?.email||null,createdAt:new Date().toISOString()});localStorage.setItem('mnu-community-feedback',JSON.stringify(items))}catch{toast('Не удалось сохранить отзыв в этом браузере');return}e.currentTarget.reset();feedbackDialog.close();toast('Отзыв сохранён в этом браузере (демо)')});
document.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.closeDialog)?.close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));$('.brand').addEventListener('click',e=>{e.preventDefault();setView('home')});document.addEventListener('click',e=>{const action=e.target.closest('[data-announcement-action]')?.dataset.announcementAction;if(action==='meetup'){const eventsTab=$('[data-club-tab="events"]');eventsTab?.click();$('#clubContent')?.scrollIntoView({behavior:'smooth',block:'start'})}if(action==='idea'){if(!ensureSignedIn(()=>{feedbackDialog.showModal();$('#feedbackForm').elements.topic.value='Идея для AI-хакатона';$('#feedbackForm').elements.message.focus()}))return}});updateAccountChrome();
